INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 22, 'theory', 'Quiz: parallelism in architecture');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 0, 'Why do processors get more and more cores instead of higher frequency?', '["Cores are cheaper to make", "Power grows roughly as the cube of frequency: several slow cores do the same work with less heat", "It makes programs easier to write", "Frequency is limited by law"]', 1, 'Two cores at half the frequency give the same total performance at a quarter of the power.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 1, 'What does a cache coherence protocol (for example MESI) do?', '["Speeds up the bus", "Guarantees that all cores eventually see the same value of every cell: a write invalidates other copies", "Encrypts the cache", "Distributes threads across cores"]', 1, 'The modified copy of a line is always unique; other cores get it after a read or a request.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 2, 'What is false sharing?', '["Two threads write to the same variable", "Threads write to different variables that lie in one cache line, and the line keeps moving between cores", "A protocol error", "Running out of cache"]', 1, 'Coherence works at the level of lines; aligning the "hot" data of different threads to the line size helps.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 3, 'How does compare-and-swap (CAS) work?', '["Swaps the values of two registers", "Atomically writes a new value if the current one equals the expected one, and reports success", "Locks all memory", "Copies a cache line"]', 1, 'The loop "read, try to replace, repeat on failure" gives an atomic counter without locking.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 4, 'Why do branches slow down a GPU?', '["A GPU has no jump instructions", "The threads of a warp execute one instruction: when conditions diverge, both branches run one after the other", "Conditions are evaluated on the CPU", "Branches are forbidden"]', 1, 'This is called divergence; a GPU works best on uniform computations.');
